insert into public.dsr_item (source,rate_year,code,chapter,subhead,description,unit,rate,billable) values
('DSR','2023','12.45.1','12.0','ROOFING','Providing and fixing false ceiling at all heights including providing and fixing of frame work made of special sections, power pressed from M.S. sheets and galvanized with zinc coating of 120 gms/sqm (both side inclusive) as per IS : 277 and consisting of angle cleats of size 25 mm wide x 1.6 mm thick with flanges of 27 mm and 37mm, at 1200 mm centre to centre, one flange fixed to the ceiling with dash fastener 12.5 mm dia x 50 mm long with 6 mm dia bolts, other flange of cleat fixed to the angle hangers of 25x10x0.50 mm of required length with nuts & bolts of required size and other end of angle hanger fixed with intermediate G.I. channels 45x15x0.9 mm running at the spacing of 1200 mm centre to centre, to which the ceiling section 0.5 mm thick bottom wedge of 80 mm with tapered flanges of 26 mm each having lips of 10.5 mm, at 450 mm centre to centre, shall be fixed in a direction perpendicular to G.I. intermediate channel with connecting clips made out of 2.64 mm dia x 230 mm long G.I. wire at every junction, including fixing perimeter channels 0.5 mm thick 27 mm high having flanges of 20 mm and 30 mm long, the perimeter of ceiling fixed to wall/partition with the help of rawl plugs at 450 mm centre, with 25 mm long dry wall screws @ 230 mm interval, including fixing of gypsum board to ceiling section and perimeter channel with the help of dry wall screws of size 3.5 x 25 mm at 230 mm c/c, including jointing and finishing to a flush finish of tapered and square edges of the board with recommended jointing compound , jointing tapes , finishing with jointing compound in 3 layers covering upto 150 mm on both sides of joint and two coats of primer suitable for board, all as per manufacturer’s specification and also including the cost of making openings for light fittings, grills, diffusers, cutouts made with frame of perimeter channels suitably fixed, all complete as per drawings, specification and direction of the Engineer in Charge but excluding the cost of painting with : — 12.5 mm thick tapered edge gypsum plain board conforming to IS: 2095- (Part I) :2011 (Board with BIS certification marks)','sqm',1355.80,true),
('DSR','2023','12.45.2','12.0','ROOFING','Providing and fixing false ceiling at all heights including providing and fixing of frame work made of special sections, power pressed from M.S. sheets and galvanized with zinc coating of 120 gms/sqm (both side inclusive) as per IS : 277 and consisting of angle cleats of size 25 mm wide x 1.6 mm thick with flanges of 27 mm and 37mm, at 1200 mm centre to centre, one flange fixed to the ceiling with dash fastener 12.5 mm dia x 50 mm long with 6 mm dia bolts, other flange of cleat fixed to the angle hangers of 25x10x0.50 mm of required length with nuts & bolts of required size and other end of angle hanger fixed with intermediate G.I. channels 45x15x0.9 mm running at the spacing of 1200 mm centre to centre, to which the ceiling section 0.5 mm thick bottom wedge of 80 mm with tapered flanges of 26 mm each having lips of 10.5 mm, at 450 mm centre to centre, shall be fixed in a direction perpendicular to G.I. intermediate channel with connecting clips made out of 2.64 mm dia x 230 mm long G.I. wire at every junction, including fixing perimeter channels 0.5 mm thick 27 mm high having flanges of 20 mm and 30 mm long, the perimeter of ceiling fixed to wall/partition with the help of rawl plugs at 450 mm centre, with 25 mm long dry wall screws @ 230 mm interval, including fixing of gypsum board to ceiling section and perimeter channel with the help of dry wall screws of size 3.5 x 25 mm at 230 mm c/c, including jointing and finishing to a flush finish of tapered and square edges of the board with recommended jointing compound , jointing tapes , finishing with jointing compound in 3 layers covering upto 150 mm on both sides of joint and two coats of primer suitable for board, all as per manufacturer’s specification and also including the cost of making openings for light fittings, grills, diffusers, cutouts made with frame of perimeter channels suitably fixed, all complete as per drawings, specification and direction of the Engineer in Charge but excluding the cost of painting with : — 12.5 mm thick tapered edge Glass Reinforced Gypsum (GRG) board conforming to IS: 2095- (Part 3):1996 (Boards with BIS certification marks)','sqm',1520.10,true),
('DSR','2023','12.45.3','12.0','ROOFING','Providing and fixing false ceiling at all heights including providing and fixing of frame work made of special sections, power pressed from M.S. sheets and galvanized with zinc coating of 120 gms/sqm (both side inclusive) as per IS : 277 and consisting of angle cleats of size 25 mm wide x 1.6 mm thick with flanges of 27 mm and 37mm, at 1200 mm centre to centre, one flange fixed to the ceiling with dash fastener 12.5 mm dia x 50 mm long with 6 mm dia bolts, other flange of cleat fixed to the angle hangers of 25x10x0.50 mm of required length with nuts & bolts of required size and other end of angle hanger fixed with intermediate G.I. channels 45x15x0.9 mm running at the spacing of 1200 mm centre to centre, to which the ceiling section 0.5 mm thick bottom wedge of 80 mm with tapered flanges of 26 mm each having lips of 10.5 mm, at 450 mm centre to centre, shall be fixed in a direction perpendicular to G.I. intermediate channel with connecting clips made out of 2.64 mm dia x 230 mm long G.I. wire at every junction, including fixing perimeter channels 0.5 mm thick 27 mm high having flanges of 20 mm and 30 mm long, the perimeter of ceiling fixed to wall/partition with the help of rawl plugs at 450 mm centre, with 25 mm long dry wall screws @ 230 mm interval, including fixing of gypsum board to ceiling section and perimeter channel with the help of dry wall screws of size 3.5 x 25 mm at 230 mm c/c, including jointing and finishing to a flush finish of tapered and square edges of the board with recommended jointing compound , jointing tapes , finishing with jointing compound in 3 layers covering upto 150 mm on both sides of joint and two coats of primer suitable for board, all as per manufacturer’s specification and also including the cost of making openings for light fittings, grills, diffusers, cutouts made with frame of perimeter channels suitably fixed, all complete as per drawings, specification and direction of the Engineer in Charge but excluding the cost of painting with : — 12.5 mm thick tapered edge gypsum moisture resistant board','sqm',1529.10,true),
('DSR','2023','12.45.4','12.0','ROOFING','Providing and fixing false ceiling at all heights including providing and fixing of frame work made of special sections, power pressed from M.S. sheets and galvanized with zinc coating of 120 gms/sqm (both side inclusive) as per IS : 277 and consisting of angle cleats of size 25 mm wide x 1.6 mm thick with flanges of 27 mm and 37mm, at 1200 mm centre to centre, one flange fixed to the ceiling with dash fastener 12.5 mm dia x 50 mm long with 6 mm dia bolts, other flange of cleat fixed to the angle hangers of 25x10x0.50 mm of required length with nuts & bolts of required size and other end of angle hanger fixed with intermediate G.I. channels 45x15x0.9 mm running at the spacing of 1200 mm centre to centre, to which the ceiling section 0.5 mm thick bottom wedge of 80 mm with tapered flanges of 26 mm each having lips of 10.5 mm, at 450 mm centre to centre, shall be fixed in a direction perpendicular to G.I. intermediate channel with connecting clips made out of 2.64 mm dia x 230 mm long G.I. wire at every junction, including fixing perimeter channels 0.5 mm thick 27 mm high having flanges of 20 mm and 30 mm long, the perimeter of ceiling fixed to wall/partition with the help of rawl plugs at 450 mm centre, with 25 mm long dry wall screws @ 230 mm interval, including fixing of gypsum board to ceiling section and perimeter channel with the help of dry wall screws of size 3.5 x 25 mm at 230 mm c/c, including jointing and finishing to a flush finish of tapered and square edges of the board with recommended jointing compound , jointing tapes , finishing with jointing compound in 3 layers covering upto 150 mm on both sides of joint and two coats of primer suitable for board, all as per manufacturer’s specification and also including the cost of making openings for light fittings, grills, diffusers, cutouts made with frame of perimeter channels suitably fixed, all complete as per drawings, specification and direction of the Engineer in